reference_solution:
def count_subarrays_with_frequent_maximum(nums,k):
    maximum=max(nums);left=occurrences=answer=0
    for value in nums:
        occurrences+=value==maximum
        while occurrences>=k:
            occurrences-=nums[left]==maximum;left+=1
        answer+=left
    return answer

